class LionSwitch(Component):
    tag = "lion-switch"
    schema = ComponentSchema(
        tag="lion-switch",
        class_name="LionSwitch",
        summary="",
        props=(
            PropertySchema(name="checked", kind="boolean", choices=(), default=None, description=None),
            PropertySchema(
                name="disabled",
                kind="boolean",
                choices=(),
                default="false",
                description="Boolean indicating whether or not this element is disabled.",
            ),
            PropertySchema(
                name="modelValue",
                kind="json",
                choices=(),
                type_text="{value:string|any,checked:boolean}",
                default=None,
                description="Whereas 'normal' `.modelValue`s usually store a complex/typed version\nof a view value, choice inputs have a slightly different approach.\nIn order to remain their Single Source of Truth characteristic, choice inputs\nstore both the value and 'checkedness', in the format { value: 'x', checked: true }\nDifferent from the platform, this also allows to serialize the 'non checkedness',\nallowing to restore form state easily and inform the server about unchecked options.",
            ),
            PropertySchema(
                name="choiceValue",
                kind="json",
                choices=(),
                type_text="string|any",
                default=None,
                description="The value that will be registered to the modelValue of the parent ChoiceGroup. Recommended\nto be a string",
            ),
            PropertySchema(
                name="readonly",
                kind="boolean",
                choices=(),
                default="false",
                description="A Boolean attribute which, if present, indicates that the user should not be able to edit\nthe value of the input. The difference between disabled and readonly is that read-only\ncontrols can still function, whereas disabled controls generally do not function as\ncontrols until they are enabled.\n(From: https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input#attr-readonly)",
            ),
            PropertySchema(
                name="label",
                kind="string",
                choices=(),
                default=None,
                description="The label text for the input node.\nWhen no light dom defined via [slot=label], this value will be used.",
            ),
            PropertySchema(
                name="label-sr-only",
                kind="boolean",
                choices=(),
                default="false",
                description="The label will only be visible for srceen readers when true",
            ),
            PropertySchema(
                name="help-text",
                kind="string",
                choices=(),
                default=None,
                description="The helpt text for the input node.\nWhen no light dom defined via [slot=help-text], this value will be used",
            ),
            PropertySchema(
                name="name",
                kind="string",
                choices=(),
                default="",
                description="The name the element will be registered with to the .formElements collection\nof the parent. Also, it serves as the key of key/value pairs in\n modelValue/serializedValue objects",
            ),
            PropertySchema(
                name="allow-cross-root-registration",
                kind="boolean",
                choices=(),
                default="false",
                description="To encourage accessibility best practices, `form-element-register` events\ndo not pierce through shadow roots. This forces the developer to create form groups and fieldsets that automatically allow the creation of accessible relationships in the same dom tree.\nUse this option if you know what you're doing. It will then be possible to nest FormControls\ninside shadow dom. See https://lion.js.org/fundamentals/rationales/accessibility/#shadow-roots-and-accessibility",
            ),
            PropertySchema(
                name="touched", kind="boolean", choices=(), default="false", description="True when user has focused and left(blurred) the field."
            ),
            PropertySchema(
                name="dirty", kind="boolean", choices=(), default="false", description="True when user has changed the value of the field."
            ),
            PropertySchema(
                name="filled",
                kind="boolean",
                choices=(),
                default="false",
                description="True when the modelValue is non-empty (see _isEmpty in FormControlMixin)",
            ),
            PropertySchema(
                name="focused",
                kind="boolean",
                choices=(),
                default="false",
                description="Whether the focusable element within (`._focusableNode`) is focused.\nReflects to attribute '[focused]' as a styling hook",
            ),
            PropertySchema(
                name="focused-visible",
                kind="boolean",
                choices=(),
                default="false",
                description="Whether the focusable element within (`._focusableNode`) matches ':focus-visible'\nReflects to attribute '[focused-visible]' as a styling hook\nSee: https://developer.mozilla.org/en-US/docs/Web/CSS/:focus-visible",
            ),
            PropertySchema(name="autofocus", kind="boolean", choices=(), default="false", description=None),
            PropertySchema(
                name="shows-feedback-for",
                kind="json",
                choices=(),
                type_text="ValidationType[]",
                default=None,
                description='Based on outcome of feedbackCondition, this array decides what ValidationTypes should be\nshown in validationFeedback, based on meta data like interaction states.\n\nFor styling purposes, it reflects it `[shows-feedback-for="error warning"]`',
            ),
            PropertySchema(
                name="is-pending",
                kind="boolean",
                choices=(),
                default="false",
                description="Flag indicating whether async validation is pending.\nCreates attribute [is-pending] as a styling hook",
            ),
        ),
        events=(
            "model-value-changed",
            "user-input-changed",
            "form-element-name-changed",
            "form-element-register",
            "touched-changed",
            "dirty-changed",
            "focus",
            "blur",
            "focusin",
            "focusout",
            "showsFeedbackForChanged",
            "shouldShowFeedbackForChanged",
            "validate-performed",
        ),
        slots=(),
    )

    def __init__(
        self,
        *children: Child,
        key: str | None = None,
        checked: bool | None = None,
        disabled: bool | None = None,
        modelValue: Any = None,
        choiceValue: Any = None,
        readonly: bool | None = None,
        label: str | None = None,
        label_sr_only: bool | None = None,
        help_text: str | None = None,
        name: str | None = None,
        allow_cross_root_registration: bool | None = None,
        touched: bool | None = None,
        dirty: bool | None = None,
        filled: bool | None = None,
        focused: bool | None = None,
        focused_visible: bool | None = None,
        autofocus: bool | None = None,
        shows_feedback_for: Any = None,
        is_pending: bool | None = None,
        **props: Any,
    ) -> None:
        super().__init__(
            *children,
            key=key,
            props={
                "checked": checked,
                "disabled": disabled,
                "modelValue": modelValue,
                "choiceValue": choiceValue,
                "readonly": readonly,
                "label": label,
                "label-sr-only": label_sr_only,
                "help-text": help_text,
                "name": name,
                "allow-cross-root-registration": allow_cross_root_registration,
                "touched": touched,
                "dirty": dirty,
                "filled": filled,
                "focused": focused,
                "focused-visible": focused_visible,
                "autofocus": autofocus,
                "shows-feedback-for": shows_feedback_for,
                "is-pending": is_pending,
            },
            **props,
        )


